package com.nutritionplatform.progress.controller;
import com.nutritionplatform.progress.dto.ProgressRequests; import com.nutritionplatform.progress.service.ProgressService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/v1/progress") public class ProgressController { private final ProgressService service; public ProgressController(ProgressService service){this.service=service;} @GetMapping("/weights") public java.util.List<java.util.Map<String,Object>> weights(Authentication a){return service.weights((UUID)a.getPrincipal());} @PostMapping("/checkins") @ResponseStatus(HttpStatus.CREATED) public void checkin(Authentication a,@Valid @RequestBody ProgressRequests.Checkin r){service.checkin((UUID)a.getPrincipal(),r);} @PostMapping("/weights") @ResponseStatus(HttpStatus.CREATED) public void weight(Authentication a,@Valid @RequestBody ProgressRequests.Weight r){service.weight((UUID)a.getPrincipal(),r);} @PostMapping("/measurements") @ResponseStatus(HttpStatus.CREATED) public void measurement(Authentication a,@Valid @RequestBody ProgressRequests.Measurement r){service.measurement((UUID)a.getPrincipal(),r);} }
